"""Read key-value pairs from stdin and sum the values for each key.

Input: one pair per line, "KEY VALUE", separated by whitespace.
Output: one line per key, "KEY SUM", in the order keys were first seen.
Author: your name
Date: 2025-12-18
"""
import sys

def main():
    totals = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) < 2:
            continue
        key = parts[0]
        try:
            value = int(parts[1])
        except ValueError:
            continue
        if key in totals:
            totals[key] += value
        else:
            totals[key] = value
    for key, total in totals.items():
        print(key, total)

if __name__ == "__main__":
    main()
